// Build seat allocation payload
// The customer data comes from Heroku GET /orders/seats/{order_id}
const orderData = $input.first().json;
const triggerData = $('Execute Trigger').item.json;
const statePayload = triggerData.state_payload || {};

const customers = orderData.customers || [];
const orderId = triggerData.order_id;
const tripId = statePayload.trip_id;

// Build order_customers_attributes mapping (using index '0' for first passenger)
const orderCustomersAttributes = {};
customers.forEach((customer, idx) => {
  orderCustomersAttributes[String(idx)] = { id: String(customer.id) };
});

// Seat numbers — if the user selected a seat, use it; otherwise use '1' as a default
const seatNumbers = statePayload.seat_number ? `[${statePayload.seat_number}]` : '[1]';

const seatPayload = {
  id: String(orderId),
  order: {
    trip_id: String(tripId),
    seat_numbers: seatNumbers,
    order_customers_attributes: orderCustomersAttributes
  }
};

return [{
  json: {
    seatPayload,
    order_id: orderId,
    phone_number: triggerData.phone_number,
    full_name: triggerData.full_name || customers[0]?.name || 'Passageiro',
    voucher_url: `https://embarcar-e83ea296df06.herokuapp.com/orders/${orderId}`,
    session_id: triggerData.session_id
  }
}];

